/* <string.h> is not freestanding. Of its functions only memcpy, memmove,
 * memset and memcmp are ones a freestanding target is expected to supply
 * anyway — the compiler may emit calls to those from an ordinary struct
 * assignment — so those go through `__builtin_`, which lets it inline them
 * and otherwise calls what the target already has to provide. strlen and
 * strcmp carry no such expectation, so they are spelled out.
 */
static size_t kf_cstr_len(const char* s) {
    size_t n = 0;
    while (s[n] != '\0') n++;
    return n;
}

/* Equal when they agree up to and including the terminator — which is the
 * same walk strcmp does, minus the ordering nobody here asks for.
 */
bool str_equals(const char* left, const char* right) {
    size_t i = 0;
    while (left[i] != '\0' && left[i] == right[i]) i++;
    return left[i] == right[i];
}

const char* str_as_str(const char* value) {
    return value;
}

uint64_t kf_str_byte_len(const char* value) {
    return kf_cstr_len(value);
}

uint8_t kf_str_byte_at(const char* value, uint64_t index) {
    return (uint8_t)value[index];
}

/* argv, held rather than read. Storing what `main` was handed needs no
 * library — whoever had an argv passed it in — so this stays on the
 * freestanding side and the generated `main` can call kf_arg_init
 * unconditionally. A target with no command line calls it with (0, NULL),
 * or not at all, and the accessors answer for an empty one.
 */
static int kf_argc = 0;
static char** kf_argv = NULL;

void kf_arg_init(int argc, char** argv) {
    kf_argc = argc;
    kf_argv = argv;
}

int32_t kf_arg_count(void) {
    return kf_argc > 0 ? kf_argc - 1 : 0;
}

const char* kf_arg_get(int32_t index) {
    return kf_argv[index + 1];
}

// Reinterpret a float's bits as an integer, for hashing. A union rather than
// memcpy so this stays in the freestanding tier — `Hash` must not pull in
// libc (see libs/core/src/hash.kf).
//
// Casting (`(uint64_t)v`) would be a VALUE conversion: 1.5 and 1.9 both
// truncate to 1 and would hash alike, and every fraction below 1 would
// collide with zero.
uint64_t kf_float64_bits(double v) {
    union { double d; uint64_t u; } x;
    x.d = v;
    return x.u;
}

uint32_t kf_float32_bits(float v) {
    union { float f; uint32_t u; } x;
    x.f = v;
    return x.u;
}

/* Up to four encoded bytes as a borrowed, NUL-terminated `str`.
 *
 * `Display for char` writes its UTF-8 into a sink, and a sink takes a `str`.
 * Building one would mean an owned String for a character, which is the
 * allocation this tier is trying not to make -- and KFlat has no stack arrays
 * to put five bytes in, so the scratch space lives here.
 *
 * The encoding itself stays in KFlat (core.text.char_encode_utf8); this only
 * packs bytes it is handed, so there is one encoder and not two.
 *
 * CONSTRAINT: a returned pointer stays valid until the KF_UTF8_SLOTS-th call
 * after it, exactly like the float ring in core_hosted.c.
 */
#define KF_UTF8_SLOTS 4

static char kf_utf8_ring[KF_UTF8_SLOTS][5];
static unsigned kf_utf8_next = 0;

const char* kf_utf8_bytes_str(uint8_t b0, uint8_t b1, uint8_t b2, uint8_t b3, uint64_t width) {
    char* slot = kf_utf8_ring[kf_utf8_next];
    kf_utf8_next = (kf_utf8_next + 1) % KF_UTF8_SLOTS;
    if (width > 4) width = 0;
    if (width > 0) slot[0] = (char)b0;
    if (width > 1) slot[1] = (char)b1;
    if (width > 2) slot[2] = (char)b2;
    if (width > 3) slot[3] = (char)b3;
    slot[width] = '\0';
    return slot;
}
#ifndef KF_NATIVE_UNITY
#include "kf_runtime.h"
/* core's own generated header: the prototypes callers see for what this
 * file defines. */
#include "core.h"
#endif

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

/* core's HOSTED tier (#302).
 *
 * `core.c` next to this file is written against the three freestanding
 * headers and leaves four things declared but undefined: where memory comes
 * from, and how to stop, print and be told about the process. This file is
 * the set of answers that is right when there is a C library underneath.
 *
 * It is listed under `[native] hosted_c_sources`, so a program built with
 * `freestanding = true` does not get it and supplies its own answers
 * instead. Every symbol here is therefore a seam and not an internal: the
 * allocator trio stays weak (a hosted program can still replace it without
 * going freestanding), and the rest are strong because a program that wants
 * a different `panic` on a hosted target is describing a freestanding
 * build.
 *
 * The include list is the honest statement of what this half costs:
 * <stdio.h> for a console, <stdlib.h> for a heap and exit, <sys/wait.h> and
 * <unistd.h> for a process that can fork. None of it exists on a target
 * with no operating system, which is why it is not in the other file.
 */

/*
 * The FALLIBLE primitives. Everything above them in `core.c` — `kf_alloc`,
 * `kf_realloc`, and the failure policy between them — is derived from this
 * pair, so replacing malloc here is the whole of replacing the allocator.
 *
 * Weak, so a hosted program can define its own without editing this
 * checkout: `libcore.a` is linked into every program and its member is
 * pulled in for `runtime_println` whatever else the program does, so a
 * strong definition would collide with a replacement rather than yield to
 * it.
 */
__attribute__((weak)) void* kf_try_alloc(size_t size) {
    return malloc(size);
}

__attribute__((weak)) void* kf_try_realloc(void* ptr, size_t size) {
    return realloc(ptr, size);
}

__attribute__((weak)) void kf_free(void* ptr) {
    free(ptr);
}

/* Stopping, and putting bytes somewhere. The freestanding boundary that
 * `core.assert` is written against: an assertion needs only `Equal`, these
 * two, and nothing else.
 */
void runtime_print(const char* value) {
    fputs(value, stdout);
    fflush(stdout);
}

void runtime_println(const char* value) {
    puts(value);
    fflush(stdout);
}

void panic(const char* message) {
    puts(message);
    fflush(stdout);
    exit(1);
}

/* Floats print with the FEWEST digits that read back as the same value.
 *
 * A fixed precision is wrong in both directions: "%g" turns 0.1 + 0.2 into
 * "0.3" and quietly loses the thing the reader is usually looking for, while
 * "%.17g" turns 0.1 into "0.10000000000000001" and makes ordinary numbers
 * unreadable. Trying the short form and keeping it only when it round-trips
 * gives "0.1" for 0.1 and "0.30000000000000004" for 0.1 + 0.2 -- exact
 * either way, and short whenever short is honest.
 *
 * The digits are handed back as a borrow into the ring below rather than as an
 * owned String: `Display` writes into a sink, and a number should not need an
 * allocator to print. Formatting one needs somewhere to put the characters,
 * KFlat has no stack arrays, so the scratch space lives here.
 *
 * CONSTRAINT: a returned pointer stays valid until the KF_FLOAT_SLOTS-th call
 * after it. Every caller in core hands it straight to `write_str`, which
 * copies; a sink that formats another float from inside its own `write_str`
 * is what the slots are for, and past that depth the bytes are rewritten
 * underneath the older borrow.
 */
#define KF_FLOAT_SLOTS 8
#define KF_FLOAT_WIDTH 40

static char kf_float_ring[KF_FLOAT_SLOTS][KF_FLOAT_WIDTH];
static unsigned kf_float_next = 0;

static char* kf_float_slot(void) {
    char* slot = kf_float_ring[kf_float_next];
    kf_float_next = (kf_float_next + 1) % KF_FLOAT_SLOTS;
    return slot;
}

const char* float64_display_str(double value) {
    char* buffer = kf_float_slot();
    snprintf(buffer, KF_FLOAT_WIDTH, "%.15g", value);
    if (strtod(buffer, NULL) != value) {
        snprintf(buffer, KF_FLOAT_WIDTH, "%.17g", value);
    }
    return buffer;
}

const char* float32_display_str(float value) {
    char* buffer = kf_float_slot();
    snprintf(buffer, KF_FLOAT_WIDTH, "%.6g", (double)value);
    if ((float)strtod(buffer, NULL) != value) {
        snprintf(buffer, KF_FLOAT_WIDTH, "%.9g", (double)value);
    }
    return buffer;
}

// Asking the process about itself, alongside the argv `core.c` holds. Both
// exist for output that should look different when a person is reading it
// than when a pipe is: which of the two is a policy question, so it is
// answered by the caller and not here.

// Present AND non-empty, which is what the NO_COLOR convention specifies:
// `NO_COLOR=` set to nothing is not a request to disable anything.
bool kf_env_is_set(const char* name) {
    const char* value = getenv(name);
    return value != NULL && value[0] != '\0';
}

bool kf_stdout_is_tty(void) {
    return isatty(1) == 1;
}

// Run one `@test` in a child process: an assertion calls panic, which exits,
// so a failing test must not share a process with the rest of the suite.
//
// The child is this same binary re-exec'd with `--run-test <name>`, this
// process's argv forwarded so a flag a test reads still reaches it. Returns
// the child's exit code, or 128 if it died on a signal — a segfault or an
// ASan abort is a failed test, not a dead suite.
//
// argv comes back through the accessors rather than the statics that hold
// it: those live in the freestanding half, where storing an argv needs no
// library, and static means static.
/* Where the suite's wall clock goes.
 *
 * Recorded here rather than in the generated main so no test source and no
 * codegen has to know about it: the runner already forks each test and knows
 * its name, which is exactly the pair a report needs. Names are string
 * literals in the binary, so holding the pointer is safe for the run.
 */
static int32_t kf_test_run_child_timed(const char* name);

#define KF_TEST_SLOTS 8192
static const char*    kf_test_names[KF_TEST_SLOTS];
static unsigned long  kf_test_elapsed[KF_TEST_SLOTS];
static int            kf_test_recorded = 0;
static unsigned long  kf_test_total_ns = 0;

/* The tests that failed, listed again under the summary: a count alone sends
 * whoever reads it back to the full log, which on CI is usually truncated. */
static const char*    kf_test_failed_names[KF_TEST_SLOTS];
static int            kf_test_failed_count = 0;

void kf_test_note_failure(const char* name) {
    if (kf_test_failed_count < KF_TEST_SLOTS) kf_test_failed_names[kf_test_failed_count++] = name;
}

static unsigned long kf_now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (unsigned long)ts.tv_sec * 1000000000UL + (unsigned long)ts.tv_nsec;
}

int32_t kf_test_run_child(const char* name) {
    unsigned long started = kf_now_ns();
    int32_t code = kf_test_run_child_timed(name);
    unsigned long elapsed = kf_now_ns() - started;
    kf_test_total_ns += elapsed;
    if (kf_test_recorded < KF_TEST_SLOTS) {
        kf_test_names[kf_test_recorded] = name;
        kf_test_elapsed[kf_test_recorded] = elapsed;
        kf_test_recorded++;
    }
    return code;
}

static int32_t kf_test_run_child_timed(const char* name) {
    pid_t child = fork();
    if (child == 0) {
        int forwarded = kf_arg_count();
        char** values = (char**)kf_alloc((size_t)(forwarded + 5) * sizeof(char*));
        int n = 0;
        values[n++] = (char*)"/proc/self/exe";
        values[n++] = (char*)"--run-test";
        values[n++] = (char*)name;
        for (int i = 0; i < forwarded; i++) values[n++] = (char*)kf_arg_get(i);
        values[n] = NULL;
        execv("/proc/self/exe", values);
        _exit(127);
    }
    int status = 0;
    if (child < 0 || waitpid(child, &status, 0) < 0) return -1;
    return WIFEXITED(status) ? WEXITSTATUS(status) : 128;
}

// The summary line, and the failures above it. Formatted here so the generated
// test main needs no string vocabulary of its own: it may be testing core,
// which has no String.
/* The slowest few, because a total alone says the suite is slow without
 * saying which part to look at. Selection rather than a sort: ten passes over
 * a few thousand entries costs nothing and needs no scratch space. */
static void kf_test_print_slowest(void) {
    if (kf_test_recorded == 0) return;
    printf("  total %.1fs across %d tests\n", (double)kf_test_total_ns / 1e9, kf_test_recorded);
    int shown = kf_test_recorded < 10 ? kf_test_recorded : 10;
    unsigned long ceiling = (unsigned long)-1;
    for (int rank = 0; rank < shown; rank++) {
        int best = -1;
        for (int i = 0; i < kf_test_recorded; i++) {
            if (kf_test_elapsed[i] > ceiling) continue;
            if (best < 0 || kf_test_elapsed[i] > kf_test_elapsed[best]) best = i;
        }
        if (best < 0) break;
        /* Below a tenth of a second nothing here is worth a reader's time. */
        if (kf_test_elapsed[best] < 100000000UL) break;
        printf("  %6.2fs  %s\n", (double)kf_test_elapsed[best] / 1e9, kf_test_names[best]);
        ceiling = kf_test_elapsed[best];
        kf_test_elapsed[best] = ceiling + 1; /* consumed; excluded from the next pass */
    }
}

void kf_test_report(int32_t passed, int32_t failed) {
    if (kf_test_failed_count > 0) {
        printf("failures:\n");
        for (int i = 0; i < kf_test_failed_count; i++) printf("  %s\n", kf_test_failed_names[i]);
        printf("\n");
    }
    if (failed == 0) {
        printf("test result: ok. %d passed\n", (int)passed);
    } else {
        printf("test result: FAILED. %d passed, %d failed\n", (int)passed, (int)failed);
    }
    kf_test_print_slowest();
    fflush(stdout);
}
#ifndef KF_NATIVE_UNITY
#include "kf_runtime.h"
/* alloc's own generated header, for the `String` layout and the prototypes
 * of what this file defines. It includes core's.
 *
 * Under KF_NATIVE_UNITY everything is already one translation unit. */
#include "alloc.h"
#endif

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* `String`'s runtime half, freestanding like core.c: written against the
 * three headers above, with `memcpy` and `memmove` through `__builtin_`.
 * Its allocator is core's, which a freestanding program supplies. */
void panic(const char* message);
void* kf_alloc(size_t size);
void* kf_realloc(void* ptr, size_t size);
void kf_free(void* ptr);

/* CONSTRAINT: not `kf_cstr_len`. A unity build compiles every crate's native
 * C as one translation unit, where core.c already defines that static. */
static size_t kf_string_cstr_len(const char* s) {
    size_t n = 0;
    while (s[n] != '\0') n++;
    return n;
}

static String kf_string_from(const char* s) {
    size_t len = kf_string_cstr_len(s);
    String out;
    out.len = len;
    out.cap = len + 1;
    out.data = (uint8_t*)kf_alloc(out.cap);
    __builtin_memcpy(out.data, s, len + 1);
    return out;
}

static String kf_string_clone(const String* value) {
    return kf_string_from((const char*)value->data);
}

static void kf_string_append(String* out, const char* suffix) {
    size_t add = kf_string_cstr_len(suffix);
    if (add > SIZE_MAX - out->len - 1) panic("String length overflow");
    size_t needed = out->len + add + 1;
    size_t offset = 0;
    uintptr_t source = (uintptr_t)suffix;
    uintptr_t begin = (uintptr_t)out->data;
    bool aliases = source >= begin && source <= begin + out->len;
    if (aliases) offset = (size_t)(source - begin);
    if (needed > out->cap) {
        size_t cap = out->cap ? out->cap : 1;
        while (cap < needed) {
            if (cap > SIZE_MAX / 2) {
                cap = needed;
                break;
            }
            cap *= 2;
        }
        uint8_t* grown = (uint8_t*)kf_realloc(out->data, cap);
        out->data = grown;
        out->cap = cap;
    }
    if (aliases) suffix = (const char*)out->data + offset;
    __builtin_memmove(out->data + out->len, suffix, add + 1);
    out->len += add;
}

String __kf_v2_str_from_cstr(const char* value) {
    return kf_string_from(value);
}

String __kf_v2_str_concat(String left, String right) {
    String out = kf_string_clone(&left);
    kf_string_append(&out, (const char*)right.data);
    return out;
}

void __kf_v2_string_drop(String value) {
    kf_free(value.data);
}

String kf_str_slice_to_string(const char* value, uint64_t start, uint64_t end) {
    if (end < start) return kf_string_from("");
    size_t len = (size_t)(end - start);
    char* buffer = (char*)kf_alloc(len + 1);
    __builtin_memcpy(buffer, value + start, len);
    buffer[len] = '\0';
    String out = kf_string_from(buffer);
    kf_free(buffer);
    return out;
}
#ifndef KF_NATIVE_UNITY
#include "kf_runtime.h"
/* alloc's own generated header, for the `String` these return. */
#include "alloc.h"
#endif

#include <stdint.h>
#include <stdio.h>

/* Rendering a number is hosted because snprintf is. The String it returns is
 * built through `__kf_v2_str_from_cstr` rather than the freestanding file's
 * own `kf_string_from`, which is static: one entry point across the tier
 * boundary, and it is the one generated code already uses.
 */
String __kf_v2_int32_to_str(int32_t value) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "%d", value);
    return __kf_v2_str_from_cstr(buffer);
}

String int64_display(int64_t value) {
    char buffer[24];
    snprintf(buffer, sizeof(buffer), "%lld", (long long)value);
    return __kf_v2_str_from_cstr(buffer);
}

String uint64_display(uint64_t value) {
    char buffer[24];
    snprintf(buffer, sizeof(buffer), "%llu", (unsigned long long)value);
    return __kf_v2_str_from_cstr(buffer);
}
#ifndef KF_NATIVE_UNITY
#include "kf_runtime.h"
#endif

#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

#define KF_SYM_INITIAL_CAP 65536u

static const char** kf_sym_table;
static uint32_t kf_sym_count = 1;
static uint32_t kf_sym_capacity;
static int32_t* kf_sym_hash_table;

static uint32_t kf_sym_hash_string(const char* value) {
    uint32_t hash = 2166136261u;
    for (; *value; value++) {
        hash ^= (uint8_t)*value;
        hash *= 16777619u;
    }
    return hash;
}

static void kf_sym_allocation_failed(void) {
    static const char message[] = "komp: failed to grow symbol interner\n";
    (void)write(STDERR_FILENO, message, sizeof(message) - 1);
    _exit(1);
}

static void kf_sym_grow(void) {
    uint32_t old_capacity = kf_sym_capacity;
    uint32_t new_capacity = old_capacity == 0
        ? KF_SYM_INITIAL_CAP
        : old_capacity * 2;
    if (new_capacity <= old_capacity) kf_sym_allocation_failed();

    const char** new_symbols = (const char**)realloc(
        kf_sym_table, sizeof(const char*) * new_capacity);
    if (new_symbols == NULL) kf_sym_allocation_failed();
    memset(new_symbols + old_capacity, 0,
           sizeof(const char*) * (new_capacity - old_capacity));

    int32_t* new_hash_table = (int32_t*)calloc(new_capacity, sizeof(int32_t));
    if (new_hash_table == NULL) kf_sym_allocation_failed();

    uint32_t mask = new_capacity - 1;
    for (uint32_t id = 1; id < kf_sym_count; id++) {
        uint32_t index = kf_sym_hash_string(new_symbols[id]) & mask;
        while (new_hash_table[index] != 0) index = (index + 1) & mask;
        new_hash_table[index] = (int32_t)(id + 1);
    }

    free(kf_sym_hash_table);
    kf_sym_table = new_symbols;
    kf_sym_hash_table = new_hash_table;
    kf_sym_capacity = new_capacity;
}

uint32_t kf_sym_intern(const char* value) {
    for (;;) {
        if (kf_sym_capacity == 0) kf_sym_grow();
        uint32_t mask = kf_sym_capacity - 1;
        uint32_t index = kf_sym_hash_string(value) & mask;
        while (kf_sym_hash_table[index] != 0) {
            uint32_t id = (uint32_t)(kf_sym_hash_table[index] - 1);
            if (strcmp(kf_sym_table[id], value) == 0) return id;
            index = (index + 1) & mask;
        }

        uint64_t next_load = (uint64_t)kf_sym_count * 10;
        uint64_t load_limit = (uint64_t)kf_sym_capacity * 7;
        if (kf_sym_count >= kf_sym_capacity || next_load >= load_limit) {
            kf_sym_grow();
            continue;
        }

        char* copy = (char*)malloc(strlen(value) + 1);
        if (copy == NULL) kf_sym_allocation_failed();
        strcpy(copy, value);
        uint32_t id = kf_sym_count++;
        kf_sym_table[id] = copy;
        kf_sym_hash_table[index] = (int32_t)(id + 1);
        return id;
    }
}

const char* kf_sym_resolve(uint32_t id) {
    return kf_sym_table[id];
}

uint64_t kf_file_hash(const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return 0;
    uint64_t hash = 5381;
    unsigned char buffer[65536];
    for (;;) {
        long count = read(fd, buffer, sizeof(buffer));
        if (count <= 0) break;
        for (long i = 0; i < count; i++) hash = hash * 33 + (uint64_t)buffer[i];
    }
    close(fd);
    return hash;
}

/* Warning output, muted for the duration of a `komp test` run.
 *
 * A test run recompiles the crate, so every auto-clone and borrow hint the
 * crate's own source carries is reprinted ahead of the results — hundreds of
 * lines that say nothing about the tests and push the failures off screen.
 * `komp check` and `komp build` still report them, which is where someone
 * looking for them would go.
 *
 * A process-wide flag rather than a parameter because the print sites are
 * spread across the pipeline, and threading a display preference through
 * compilation to reach them would put it in a lot of signatures that have no
 * other reason to know.
 */
static int kf_warnings_muted = 0;

void kf_mute_warnings(int32_t on) { kf_warnings_muted = on ? 1 : 0; }
int32_t kf_warnings_are_muted(void) { return kf_warnings_muted ? 1 : 0; }

/* Which crate is being built, as a source-directory prefix.
 *
 * A warning is advice to whoever can act on it. Building anything that
 * depends on core/alloc/std used to print the dependency's borrow-ergonomics
 * advisories alongside the author's own — a consumer of `core` cannot edit
 * `core`, and under separate compilation the advice does not even name a file
 * they have (it names `core.kfi`). Errors are unaffected: a dependency that
 * fails to compile is always the consumer's problem.
 *
 * Process-wide for the same reason the mute flag is: the print sites are
 * spread across the pipeline, and threading "which project am I" through
 * compilation to reach them would put it in a lot of signatures that have no
 * other reason to know.
 *
 * A dependency built in its own child process sets its OWN root, so building
 * `core` directly still reports `core`'s warnings.
 */
static char kf_local_root_buf[4096];
static int  kf_local_root_set = 0;

void kf_set_local_root(const char* path) {
    if (!path || !*path) { kf_local_root_set = 0; kf_local_root_buf[0] = 0; return; }
    size_t n = strlen(path);
    if (n >= sizeof kf_local_root_buf) n = sizeof kf_local_root_buf - 1;
    memcpy(kf_local_root_buf, path, n);
    kf_local_root_buf[n] = 0;
    kf_local_root_set = 1;
}

const char* kf_local_root(void) {
    return kf_local_root_set ? kf_local_root_buf : "";
}

/* Running one crate's compilation in a child process.
 *
 * komp frees nothing it allocates while compiling, so a build that walks a
 * dependency chain in one process pays for the WHOLE chain rather than for
 * its largest crate: 4.5 GB for `komp test compiler/kf-driver`, against
 * 1.2 GB for the same crate with its dependencies already built (#326).
 *
 * A crate's output is entirely on disk — `.kfi`, `.h`, `.c`, `.o`, `.a` and
 * the artifact manifest — so a child that compiles one crate and exits hands
 * back everything a consumer needs, and the OS reclaims the rest. That makes
 * the fork a memory decision and not an architectural one: the parent reads
 * what the child wrote, exactly as it would read a previous run's artifacts.
 *
 * Flushing before the fork matters. Anything still buffered would be
 * duplicated into the child's copy of the stream and printed twice.
 */
int32_t kf_fork_child(void) {
    fflush(NULL);
    return (int32_t)fork();
}

/* Wait for one child. Returns its exit status, or 128+signal if it was
 * killed — which is how an out-of-memory child reports itself. */
int32_t kf_wait_child_pid(int32_t pid) {
    int status = 0;
    if (waitpid((pid_t)pid, &status, 0) < 0) return -1;
    if (WIFEXITED(status)) return (int32_t)WEXITSTATUS(status);
    if (WIFSIGNALED(status)) return (int32_t)(128 + WTERMSIG(status));
    return -1;
}

/* Leave a child. `_exit` rather than `exit` so the parent's atexit handlers
 * do not run a second time in the child, but flush first so the diagnostics
 * the child printed are not lost with its buffers. */
void kf_exit_child(int32_t code) {
    fflush(NULL);
    _exit((int)code);
}
#ifndef KF_NATIVE_UNITY
#include "kf_runtime.h"
/* For the `String` layout, which alloc declares; its header includes core's. */
#include "alloc.h"
#endif

#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

uint64_t kf_fs_dir_open(const char* path) {
    return (uint64_t)(uintptr_t)opendir(path);
}

const char* kf_fs_dir_next(uint64_t handle) {
    DIR* directory = (DIR*)(uintptr_t)handle;
    if (!directory) return NULL;
    for (;;) {
        struct dirent* entry = readdir(directory);
        if (!entry) return NULL;
        const char* name = entry->d_name;
        if (name[0] == '.' && (name[1] == '\0' || (name[1] == '.' && name[2] == '\0'))) continue;
        return name;
    }
}

void kf_fs_dir_close(uint64_t handle) {
    DIR* directory = (DIR*)(uintptr_t)handle;
    if (directory) closedir(directory);
}

String read_file(const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return __kf_v2_str_from_cstr("");
    size_t cap = 4096;
    size_t len = 0;
    char* buffer = (char*)malloc(cap);
    for (;;) {
        if (cap - len < 4096) {
            cap *= 2;
            buffer = (char*)realloc(buffer, cap);
        }
        long count = read(fd, buffer + len, cap - len - 1);
        if (count <= 0) break;
        len += (size_t)count;
    }
    close(fd);
    buffer[len] = '\0';
    String out = __kf_v2_str_from_cstr(buffer);
    free(buffer);
    return out;
}

bool is_dir(const char* path) {
    struct stat status;
    if (stat(path, &status) != 0) return false;
    return (status.st_mode & S_IFMT) == S_IFDIR;
}

String join(const char* left, const char* right) {
    size_t left_len = strlen(left);
    size_t right_len = strlen(right);
    char* buffer = (char*)malloc(left_len + right_len + 2);
    memcpy(buffer, left, left_len);
    buffer[left_len] = '/';
    memcpy(buffer + left_len + 1, right, right_len);
    buffer[left_len + right_len + 1] = '\0';
    String out = __kf_v2_str_from_cstr(buffer);
    free(buffer);
    return out;
}

void write_file(const char* path, const char* content) {
    FILE* file = fopen(path, "w");
    if (!file) return;
    fputs(content, file);
    fclose(file);
}

int32_t kf_create_dir_all(const char* path) {
    char* copy = strdup(path);
    if (!copy) return -1;
    for (char* cursor = copy + 1; *cursor; cursor++) {
        if (*cursor == '/') {
            *cursor = '\0';
            mkdir(copy, 0777);
            *cursor = '/';
        }
    }
    int result = mkdir(copy, 0777);
    free(copy);
    return result == 0 || errno == EEXIST ? 0 : -1;
}

String kf_temp_dir(const char* prefix) {
    size_t size = strlen(prefix) + 20;
    char* path = (char*)malloc(size);
    snprintf(path, size, "/tmp/%s-XXXXXX", prefix);
    if (!mkdtemp(path)) {
        free(path);
        return __kf_v2_str_from_cstr("");
    }
    String out = __kf_v2_str_from_cstr(path);
    free(path);
    return out;
}

int32_t kf_remove_dir_all(const char* path) {
    DIR* directory = opendir(path);
    if (!directory) return unlink(path);
    struct dirent* entry;
    int result = 0;
    while ((entry = readdir(directory))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        size_t size = strlen(path) + strlen(entry->d_name) + 2;
        char* child = (char*)malloc(size);
        snprintf(child, size, "%s/%s", path, entry->d_name);
        struct stat status;
        if (lstat(child, &status) != 0 || (S_ISDIR(status.st_mode) ? kf_remove_dir_all(child) : unlink(child)) != 0) result = -1;
        free(child);
    }
    closedir(directory);
    if (result == 0 && rmdir(path) != 0) result = -1;
    return result;
}

/* ─── Per-invocation scratch (#65) ─────────────────────────────────── */

/* A fixture that writes to a fixed `/tmp` name is shared state: the same
 * fixture in another checkout, or a second run of the same suite, writes
 * the same files underneath it. These answer a private directory instead.
 *
 * The root is published in the environment so a forked or exec'd child
 * agrees with its parent about where it is, and removed at exit only by
 * the process that made it. KOMP_KEEP_SCRATCH leaves it for inspection.
 *
 * An unrelated process makes its own root rather than finding this one, so
 * "private" means private to a process TREE. komp's test harness forks per
 * test, which lands one root per test — measured at 5 roots for libs/std's
 * 5 scratch-using tests. That is finer isolation than the fixed paths ever
 * had, and it is why no test may depend on a fixture another one built.
 */

#define KF_SCRATCH_CACHE 512

static char kf_scratch_root_path[512];
static int kf_scratch_is_ours = 0;
static char* kf_scratch_names[KF_SCRATCH_CACHE];
static char* kf_scratch_values[KF_SCRATCH_CACHE];
static int kf_scratch_cached = 0;

static void kf_scratch_cleanup(void) {
    if (kf_scratch_is_ours && !getenv("KOMP_KEEP_SCRATCH")) {
        kf_remove_dir_all(kf_scratch_root_path);
    }
}

const char* kf_scratch_root(void) {
    if (kf_scratch_root_path[0]) return kf_scratch_root_path;
    const char* inherited = getenv("KOMP_SCRATCH_ROOT");
    if (inherited && *inherited) {
        snprintf(kf_scratch_root_path, sizeof kf_scratch_root_path, "%s", inherited);
        return kf_scratch_root_path;
    }
    const char* base = getenv("TMPDIR");
    if (!base || !*base) base = "/tmp";
    snprintf(kf_scratch_root_path, sizeof kf_scratch_root_path, "%s/komp-XXXXXX", base);
    if (!mkdtemp(kf_scratch_root_path)) {
        /* Nowhere to be private: the fixed path is wrong but it works. */
        snprintf(kf_scratch_root_path, sizeof kf_scratch_root_path, "%s", base);
        return kf_scratch_root_path;
    }
    kf_scratch_is_ours = 1;
    setenv("KOMP_SCRATCH_ROOT", kf_scratch_root_path, 1);
    atexit(kf_scratch_cleanup);
    return kf_scratch_root_path;
}

/* Interned, so the answer can be a `str` and sit wherever the fixed path
 * used to. Past the cache it is a fresh allocation each call, which only
 * a caller naming more than KF_SCRATCH_CACHE distinct subpaths reaches. */
const char* kf_scratch_path(const char* name) {
    for (int i = 0; i < kf_scratch_cached; i++) {
        if (strcmp(kf_scratch_names[i], name) == 0) return kf_scratch_values[i];
    }
    const char* root = kf_scratch_root();
    size_t size = strlen(root) + strlen(name) + 2;
    char* path = (char*)malloc(size);
    snprintf(path, size, "%s/%s", root, name);
    if (kf_scratch_cached < KF_SCRATCH_CACHE) {
        kf_scratch_names[kf_scratch_cached] = strdup(name);
        kf_scratch_values[kf_scratch_cached] = path;
        kf_scratch_cached++;
    }
    return path;
}
